def check_n(n):
    """
    Checks if the product S(n)S(n+1)...S(n+37) is NOT a multiple of 11.
    This is equivalent to checking if NONE of the factors S(n+i) is a multiple of 11.
    """
    for i in range(38):
        k = n + i
        s_k = S(k)
        if s_k % 11 == 0:
            # Found a factor divisible by 11, so the product IS a multiple of 11.
            return False
    # No factor was divisible by 11. The product is NOT a multiple of 11.
    return True

